package com.crypto.laplace.scheduler;
import com.crypto.laplace.pool.*; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Slf4j @Component @RequiredArgsConstructor @ConditionalOnProperty(prefix="trading.laplace",name="enabled",havingValue="true") public class LaplaceCoinPoolScheduler implements ApplicationRunner { private final LaplaceCoinPoolRepository repository; private final LaplaceCoinPoolService service; @Override public void run(ApplicationArguments args){if(repository.findByStateIn(java.util.List.of(LaplaceCoinPoolState.ACTIVE,LaplaceCoinPoolState.WAITING_FOR_NEW_TREND,LaplaceCoinPoolState.PENDING_REMOVAL)).isEmpty()) runScan();} @Scheduled(cron="${trading.laplace.pool-cron}",zone="${trading.laplace.pool-zone}") public void runScan(){try{service.scan();}catch(RuntimeException e){log.error("LAPLACE_POOL_SCAN_FAILED existingPoolPreserved=true",e);}} }
